package com.payflow.auth;
import org.springframework.web.bind.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.util.*; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.util.Date;
@RestController @RequestMapping("/auth") public class AuthController { private final UserRepo repo; private final PasswordEncoder enc; private final String secret="payflow-demo-secret-change-in-production-123456789"; public AuthController(UserRepo r,PasswordEncoder e){repo=r;enc=e;}
@PostMapping("/register") public Map<String,Object> register(@RequestBody Map<String,String> b){if(repo.findByEmail(b.get("email")).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"An account with this email already exists");User u=new User();u.name=b.get("name");u.email=b.get("email");u.password=enc.encode(b.get("password"));repo.save(u);return token(u);}
@PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,String> b){User u=repo.findByEmail(b.get("email")).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!enc.matches(b.get("password"),u.password))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return token(u);}
private Map<String,Object> token(User u){String t=Jwts.builder().subject(u.email).claim("role",u.role).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).compact();return Map.of("token",t,"userId",u.id,"name",u.name,"email",u.email,"role",u.role);}}
